import itertools
import json

def solve_puzzle():
    houses = [1, 2, 3, 4]

    # Attributes as specified in the puzzle
    names = ["Eric", "Arnold", "Peter", "Alice"]
    hair_colors = ["blonde", "black", "brown", "red"]
    music_genres = ["pop", "jazz", "rock", "classical"]

    solutions = []

    for name_perm in itertools.permutations(names):
        # Indices by name for quick checks
        idx_name = {name_perm[i]: i for i in range(4)}

        for hair_perm in itertools.permutations(hair_colors):
            # Constraint 3: The person who has brown hair is not in the first house.
            if hair_perm[0] == "brown":
                continue

            # Constraint 1: Eric is the person who has red hair.
            if idx_name["Eric"] != hair_perm.index("red"):
                continue

            for music_perm in itertools.permutations(music_genres):
                # Constraint 5: The person who loves classical music is in the first house.
                if music_perm[0] != "classical":
                    continue

                # Constraint 2: The person who loves classical music is directly left of the person who has blonde hair.
                idx_classical = music_perm.index("classical")
                idx_blonde = hair_perm.index("blonde")
                if idx_classical + 1 != idx_blonde:
                    continue

                # Constraint 4: The person who loves pop music is not in the third house.
                if music_perm[2] == "pop":
                    continue

                # Constraint 6: The person who loves jazz music is the person who has red hair.
                if music_perm.index("jazz") != hair_perm.index("red"):
                    continue

                # Constraint 7: The person who loves rock music is Arnold.
                if music_perm.index("rock") != idx_name["Arnold"]:
                    continue

                # Constraint 8: Peter is somewhere to the right of the person who loves rock music.
                if idx_name["Peter"] <= music_perm.index("rock"):
                    continue

                # All constraints satisfied; record solution
                solution = {
                    "House": [str(h) for h in houses],
                    "name": list(name_perm),
                    "hair colors": list(hair_perm),
                    "favorite music genres": list(music_perm),
                }
                solutions.append(solution)

    # Prepare JSON output
    if not solutions:
        raise RuntimeError("No solution found.")
    # Assuming unique solution
    sol = solutions[0]
    header = ["House", "name", "hair colors", "favorite music genres"]
    rows = []
    for i in range(4):
        rows.append([
            sol["House"][i],
            sol["name"][i],
            sol["hair colors"][i],
            sol["favorite music genres"][i],
        ])
    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    print(json.dumps(output, ensure_ascii=False, indent=2))

if __name__ == "__main__":
    solve_puzzle()
